begin;
create function pg_temp.profile_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'PROFILE TEST FAILED: %',label;end if;end $$;
create function pg_temp.profile_denied(statement text,expected text default '42501') returns void language plpgsql as $$begin
 begin execute statement;exception when others then if sqlstate=expected then return;end if;raise exception 'Expected %, got % (%)',expected,sqlstate,sqlerrm;end;raise exception 'PROFILE TEST FAILED: permitted %',statement;
end $$;
insert into auth.users(id,email,email_confirmed_at) values('10000000-0000-4000-8000-000000000001','photo-alice@example.invalid',now()),('20000000-0000-4000-8000-000000000002','photo-bob@example.invalid',now()),('30000000-0000-4000-8000-000000000003','photo-eve@example.invalid',now());
update realm_private.accounts set state='active';
select pg_temp.profile_assert(realm_private.valid_profile_style(realm_private.default_profile_style()),'default style valid');
select pg_temp.profile_assert(not realm_private.valid_profile_style(jsonb_set(realm_private.default_profile_style(),'{font}','"script"')),'font allowlist');
select pg_temp.profile_assert(not realm_private.valid_profile_style(jsonb_set(realm_private.default_profile_style(),'{font}','null')),'null font denied');
select pg_temp.profile_assert(not realm_private.valid_profile_style(jsonb_set(realm_private.default_profile_style(),'{surface}','"url(evil)"')),'CSS injection denied');
select pg_temp.profile_assert(not realm_private.valid_profile_style(jsonb_set(realm_private.default_profile_style(),'{banner_x}','101')),'crop bounds');
select pg_temp.profile_assert(not realm_private.valid_profile_style(jsonb_set(realm_private.default_profile_style(),'{sections}','["about","about","photos","member","details"]')),'duplicate section denied');
select pg_temp.profile_assert(not has_function_privilege('authenticated','public.profile_media_operation(uuid,text,uuid,uuid,text,text,integer,integer,integer)','EXECUTE'),'browser cannot attest an upload');
select pg_temp.profile_assert(not has_function_privilege('anon','public.get_profile_card(uuid,uuid)','EXECUTE'),'anon card denied');
set local role service_role;
select set_config('profile.test.avatar',(public.profile_media_operation('10000000-0000-4000-8000-000000000001','reserve',p_client=>'10000000-0000-4000-8000-000000000011',p_kind=>'avatar',p_mime=>'image/webp',p_bytes=>100,p_width=>100,p_height=>100)->>'id'),true);
select set_config('profile.test.banner',(public.profile_media_operation('10000000-0000-4000-8000-000000000001','reserve',p_client=>'10000000-0000-4000-8000-000000000012',p_kind=>'banner',p_mime=>'image/png',p_bytes=>200,p_width=>500,p_height=>200)->>'id'),true);
select set_config('profile.test.photo',(public.profile_media_operation('10000000-0000-4000-8000-000000000001','reserve',p_client=>'10000000-0000-4000-8000-000000000013',p_kind=>'photo',p_mime=>'image/jpeg',p_bytes=>300,p_width=>500,p_height=>500)->>'id'),true);
select public.profile_media_operation('10000000-0000-4000-8000-000000000001','finish',p_id=>current_setting('profile.test.avatar')::uuid);
select public.profile_media_operation('10000000-0000-4000-8000-000000000001','finish',p_id=>current_setting('profile.test.banner')::uuid);
select public.profile_media_operation('10000000-0000-4000-8000-000000000001','finish',p_id=>current_setting('profile.test.photo')::uuid);
select pg_temp.profile_assert(public.profile_media_operation('10000000-0000-4000-8000-000000000001','reserve',p_client=>'10000000-0000-4000-8000-000000000011',p_kind=>'avatar',p_mime=>'image/webp',p_bytes=>100,p_width=>100,p_height=>100)->>'id'=current_setting('profile.test.avatar'),'upload reserve idempotent');
select pg_temp.profile_denied($q$select public.profile_media_operation('10000000-0000-4000-8000-000000000001','reserve',p_client=>'10000000-0000-4000-8000-000000000011',p_kind=>'avatar',p_mime=>'image/webp',p_bytes=>101,p_width=>100,p_height=>100)$q$,'PT409');
reset role;
insert into storage.objects(bucket_id,name) select 'realm-profiles',object_path from public.profile_media;
-- Generic permissive policies must not weaken the profile bucket's guards.
create policy fixture_storage_all on storage.objects for all to authenticated using(true) with check(true);
grant usage on schema storage to anon;grant select,insert,update,delete on storage.objects to anon;
create policy fixture_anon_storage_all on storage.objects for all to anon using(true) with check(true);
set local role anon;
select pg_temp.profile_assert((select count(*)=0 from storage.objects),'anon cannot read profile blobs under generic policy');
select pg_temp.profile_denied($q$insert into storage.objects(bucket_id,name) values('realm-profiles','anonymous-spoof.webp')$q$);
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select pg_temp.profile_assert(jsonb_array_length(public.get_profile_card('10000000-0000-4000-8000-000000000001')->'media')=0,'unpublished uploads private');
select pg_temp.profile_assert((select count(*)=0 from storage.objects),'unpublished blobs private despite generic policy');
select pg_temp.profile_assert((select count(*)=1 from public.profile_cards),'raw card rows owner only');
select pg_temp.profile_denied($q$insert into storage.objects(bucket_id,name) values('realm-profiles','spoof.webp')$q$);
select pg_temp.profile_denied($q$update public.profile_cards set about='spoof'$q$);
select pg_temp.profile_denied($q$select public.save_profile_card('{}','{}',0,0)$q$,'22023');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select set_config('profile.test.character',(select character::text from public.profile_appearances where user_id=auth.uid()),true);
select public.save_profile_card((public.get_profile_card()->'profile')||'{"display_name":"Alice account","bio":"A short intro"}',
 (public.get_profile_card()->'card')||jsonb_build_object('avatar_id',current_setting('profile.test.avatar'),'banner_id',current_setting('profile.test.banner'),'gallery',jsonb_build_array(current_setting('profile.test.photo')),'pronouns','she/her','about','My own account profile','status','Reading','connections','[{"title":"Website","url":"https://example.com"}]'::jsonb,'details','[{"label":"Favorite book","value":"A real custom field"}]'::jsonb),0,0);
select pg_temp.profile_assert(public.get_identity()->'profile'->>'avatar_path' like '%webp','account identity exposes photo path');
select pg_temp.profile_assert((select character::text=current_setting('profile.test.character') from public.profile_appearances where user_id=auth.uid()),'account changes never alter world character');
select pg_temp.profile_denied($q$select public.save_profile_card(public.get_profile_card()->'profile',public.get_profile_card()->'card',0,0)$q$,'PT409');
select pg_temp.profile_denied($q$select public.save_profile_card(public.get_profile_card()->'profile',(public.get_profile_card()->'card')||'{"connections":[{"title":"evil","url":"javascript:alert(1)"}]}',1,1)$q$,'22023');
select pg_temp.profile_denied(format('select public.save_profile_card(public.get_profile_card()->''profile'',(public.get_profile_card()->''card'')||jsonb_build_object(''banner_id'',%L),1,1)',current_setting('profile.test.avatar')),'22023');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select pg_temp.profile_assert(jsonb_array_length(public.get_profile_card('10000000-0000-4000-8000-000000000001')->'media')=3,'published media shared');
select pg_temp.profile_assert((select count(*)=3 from storage.objects),'authorized blobs readable');
select pg_temp.profile_assert((select count(*)=1 from public.account_portraits),'narrow portrait projection');
select pg_temp.profile_denied(format('select public.save_profile_card(public.get_profile_card()->''profile'',(public.get_profile_card()->''card'')||jsonb_build_object(''avatar_id'',%L),0,0)',current_setting('profile.test.avatar')));
select public.save_profile_note('10000000-0000-4000-8000-000000000001','A private note',0);
select pg_temp.profile_assert(public.get_profile_card('10000000-0000-4000-8000-000000000001')->'note'->>'note'='A private note','viewer sees own note');
select pg_temp.profile_denied($q$select public.save_profile_note('10000000-0000-4000-8000-000000000001','stale',0)$q$,'PT409');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000003',true);
select pg_temp.profile_assert(public.get_profile_card('10000000-0000-4000-8000-000000000001')->'note'->>'note'='','third user cannot see note');
select pg_temp.profile_assert((select count(*)=0 from public.profile_notes),'notes RLS private');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select public.save_profile_card(public.get_profile_card()->'profile',jsonb_set(public.get_profile_card()->'card','{style,hidden}','["photos","details","connections","about"]'),1,1);
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select pg_temp.profile_assert(public.get_profile_card('10000000-0000-4000-8000-000000000001')->'card'->'gallery'='[]','hidden gallery redacted');
select pg_temp.profile_assert(public.get_profile_card('10000000-0000-4000-8000-000000000001')->'card'->>'about'='','hidden about redacted');
select pg_temp.profile_assert(jsonb_array_length(public.get_profile_card('10000000-0000-4000-8000-000000000001')->'media')=2,'hidden photos excluded from media projection');
select pg_temp.profile_assert((select count(*)=2 from storage.objects),'hidden gallery blob denied');
select public.set_block('10000000-0000-4000-8000-000000000001',true);
select pg_temp.profile_denied($q$select public.get_profile_card('10000000-0000-4000-8000-000000000001')$q$);
select pg_temp.profile_assert((select count(*)=0 from public.account_portraits),'block revokes photo projection');
select pg_temp.profile_assert((select count(*)=0 from storage.objects),'block revokes blob reads');
reset role;
-- Reservation budgets are atomic on the account's profile lock.
insert into public.profile_media(user_id,client_id,kind,object_path,mime,bytes,width,height)
select '20000000-0000-4000-8000-000000000002',gen_random_uuid(),'photo','quota-count-'||n,'image/png',100,10,10 from generate_series(1,30) n;
update realm_private.profile_object_gc set created_at=clock_timestamp()-interval '2 hours' where object_path like 'quota-count-%';
set local role service_role;
select pg_temp.profile_assert(jsonb_array_length(public.profile_media_gc())=0,'old pending uploads are not collected');
select pg_temp.profile_denied($q$select public.profile_media_operation('20000000-0000-4000-8000-000000000002','reserve',p_client=>gen_random_uuid(),p_kind=>'photo',p_mime=>'image/png',p_bytes=>100,p_width=>10,p_height=>10)$q$,'PT429');
reset role;
delete from public.profile_media where user_id='20000000-0000-4000-8000-000000000002';
insert into public.profile_media(user_id,client_id,kind,object_path,mime,bytes,width,height)
select '20000000-0000-4000-8000-000000000002',gen_random_uuid(),'photo','quota-bytes-'||n,'image/png',8388608,10,10 from generate_series(1,7) n;
set local role service_role;
select pg_temp.profile_denied($q$select public.profile_media_operation('20000000-0000-4000-8000-000000000002','reserve',p_client=>gen_random_uuid(),p_kind=>'photo',p_mime=>'image/png',p_bytes=>8388608,p_width=>10,p_height=>10)$q$,'PT429');
select public.profile_media_operation('30000000-0000-4000-8000-000000000003','reserve',p_client=>gen_random_uuid(),p_kind=>'photo',p_mime=>'image/png',p_bytes=>100,p_width=>10,p_height=>10) from generate_series(1,15);
select pg_temp.profile_denied($q$select public.profile_media_operation('30000000-0000-4000-8000-000000000003','reserve',p_client=>gen_random_uuid(),p_kind=>'photo',p_mime=>'image/png',p_bytes=>100,p_width=>10,p_height=>10)$q$,'PT429');
reset role;
delete from public.profile_media where user_id in ('20000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000003');
-- Discard synthetic quota fixture paths, leaving only the three real test blobs.
delete from realm_private.profile_object_gc;
set local role service_role;
select pg_temp.profile_denied(format('select public.profile_media_operation(%L,''cleanup'',p_id=>%L)','10000000-0000-4000-8000-000000000001',current_setting('profile.test.avatar')),'PT409');
reset role;
select pg_temp.profile_assert(realm_private.own_export('10000000-0000-4000-8000-000000000001')->'account_profile'->>'status'='Reading','card included in own-data export');
delete from auth.users where id='10000000-0000-4000-8000-000000000001';
select pg_temp.profile_assert((select count(*)=0 from public.profile_media),'account deletion removes media metadata');
select pg_temp.profile_assert((select count(*)=3 from realm_private.profile_object_gc),'account deletion queues physical blobs for worker');
set local role service_role;
select pg_temp.profile_assert(jsonb_array_length(public.profile_media_gc())=0,'cleanup waits for in-flight uploads');
reset role;
update realm_private.profile_object_gc set created_at=clock_timestamp()-interval '2 hours';
select set_config('profile.test.gc_path',(select object_path from realm_private.profile_object_gc limit 1),true);
set local role service_role;
select pg_temp.profile_assert(jsonb_array_length(public.profile_media_gc())=3,'old deleted-account blobs become eligible');
select public.profile_media_gc(current_setting('profile.test.gc_path'));
reset role;
select pg_temp.profile_assert((select count(*)=2 from realm_private.profile_object_gc),'successful cleanup acknowledgement removes only its queue entry');
select pg_temp.profile_assert((select count(*)=0 from public.profile_notes),'deleted target notes removed');
rollback;
